<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';$user=require_permission('documents.view');\App\Core\Tenant::enforceActive((int)$user['tenant_id']);$sql="SELECT d.*,p.name patient_name,u.name professional_name FROM clinical_documents d JOIN patients p ON p.id=d.patient_id AND p.tenant_id=d.tenant_id JOIN users u ON u.id=d.professional_id AND u.tenant_id=d.tenant_id WHERE d.tenant_id=:t";$pa=['t'=>$user['tenant_id']];if($user['role_slug']==='supervised'){$sql.=' AND d.professional_id=:u';$pa['u']=$user['id'];}elseif($user['role_slug']==='psychologist'){$sql.=' AND (d.professional_id=:professional_id OR d.supervisor_id=:supervisor_id)';$pa['professional_id']=$user['id'];$pa['supervisor_id']=$user['id'];}elseif($user['role_slug']==='clinic_admin'){$sql.=' AND (d.professional_id=:professional_id OR d.supervisor_id=:supervisor_id)';$pa['professional_id']=$user['id'];$pa['supervisor_id']=$user['id'];}$sql.=' ORDER BY d.created_at DESC LIMIT 150';$st=db()->prepare($sql);$st->execute($pa);$docs=$st->fetchAll();layout('Documentos',function()use($docs,$user){?><div class="page-head"><div><span class="eyebrow">Documentos psicológicos</span><h1>Documentos</h1><p>Declaração, atestado, relatório, laudo e parecer com revisão antes da assinatura.</p></div><?php if(\App\Core\Rbac::allows((int)$user['id'],'documents.write')):?><a class="button" href="<?=e(url('documents/new.php'))?>">+ Novo documento</a><?php endif?></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Paciente</th><th>Tipo</th><th>Título</th><th>Conformidade</th><th>Status</th><th></th></tr></thead><tbody><?php if(!$docs):?><tr><td colspan="7" class="muted">Nenhum documento acessível.</td></tr><?php endif?><?php foreach($docs as $d):?><tr><td><?=e(date('d/m/Y',strtotime($d['created_at'])))?></td><td data-private><?=e($d['patient_name'])?></td><td><?=e(ucfirst($d['document_type']))?></td><td><?=e($d['title'])?></td><td><span class="status"><?=e($d['compliance_status'])?></span></td><td><span class="status <?=e($d['status'])?>"><?=e($d['status'])?></span></td><td><a href="<?=e(url('documents/view.php?id='.$d['id']))?>">Abrir</a></td></tr><?php endforeach?></tbody></table></div></div><?php },['active'=>'documents']);
